def f(a, k):
	bad = 0
	streak = 0
	for x in a:
		if x > k:
			streak = 0
		else:
			streak += 1
			bad += streak
	return len(a) * (len(a) + 1) // 2 - bad
t = int(input())
for _ in range(t):
	(n, k) = map(int, input().split())
	a = list(map(int, input().split()))
	print(f(a, k))
